 <title>Feature card, default AI output</title>
 <!-- The slop card from lesson 3 of docs/unslop-school.html, without the course's numbered callout dots. -->
 <link rel="preconnect" href="https://fonts.googleapis.com">
-<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@500;700;800&family=JetBrains+Mono:wght@400;500&family=Instrument+Serif:ital@0;1&display=swap">
+<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Big+Shoulders+Stencil+Display:wght@700&family=Barlow:wght@400;500;700&family=JetBrains+Mono:wght@400&display=swap">
 <style>
 :root{
-  --display:"Schibsted Grotesk", "Helvetica Neue", Arial, sans-serif;
+  --ground: #1C2A30;
+  --light: #E4E8E3;
+  --signal: #FF6A1F;
+  --font-display: 'Big Shoulders Stencil Display', 'Arial Narrow', sans-serif;
+  --font-body: 'Barlow', 'Helvetica Neue', Arial, sans-serif;
+  /* colour: legacy names mapped onto the harbour tokens */
+  --surface:color-mix(in oklch, var(--ground), var(--light) 7%);
+  --ink:var(--light);
+  --muted:color-mix(in oklch, var(--light) 78%, var(--ground));
+  --accent:var(--signal);
+  /* type */
+  --display:var(--font-display);
+  --body:var(--font-body);
   --mono:"JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;
+  /* spacing scale */
+  --s1:4px; --s2:8px; --s3:12px; --s4:16px; --s5:24px;
+  /* radius */
+  --r-card:20px;
 }
-.slop{background:linear-gradient(135deg,#6E4CF5 0%,#3B82F6 55%,#22D3EE 100%);padding:22px;color:#fff;position:relative}
-.slop .box{border:1px solid rgba(255,255,255,.28);background:rgba(255,255,255,.08);border-radius:22px;padding:22px}
-.slop .eb{font:500 11px/1 var(--mono);letter-spacing:.14em;color:rgba(255,255,255,.7)}
-.slop .pill{display:inline-block;font:600 10px/1 var(--display);letter-spacing:.08em;padding:5px 9px;border-radius:999px;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.3);margin-left:8px;vertical-align:middle}
-.slop h5{font:400 30px/1.1 "Instrument Serif",Georgia,serif;letter-spacing:-.03em;margin:14px 0 8px}
-.slop h5 em{font-style:italic}
-.slop .sub{font:600 11px/1.4 var(--display);letter-spacing:.12em;opacity:.75}
-.slop hr{border:0;border-top:1px solid rgba(255,255,255,.25);margin:14px 0}
-.slop .crumb{font:400 12px/1.5 var(--mono);opacity:.8}
-.slop .copy{font:400 13px/1.5 var(--display);opacity:.72;margin-top:10px}
-.slop .ctas{display:flex;gap:8px;margin-top:14px}
-.slop .ctas span{font:600 12px var(--display);padding:8px 12px;border-radius:12px;border:1px solid rgba(255,255,255,.35);background:rgba(255,255,255,.12)}
+.slop{background:var(--ground);padding:var(--s5);color:var(--ink);font-family:var(--body)}
+.slop .box{background:var(--surface);border-radius:var(--r-card);padding:var(--s5)}
+.slop h5{font:700 24px/1.2 var(--display);letter-spacing:-.01em;margin:0 0 var(--s2);text-wrap:balance;max-width:24ch}
+.slop .copy{font:400 15px/1.5 var(--body);color:var(--muted);margin:0;max-width:52ch}
+/* the plan preview is real output, so mono belongs here; inner radius = 20 - 24 padding -> clamp to a small radius */
+.slop .crumb{font:400 13px/1.6 var(--mono);color:var(--ink);background:var(--ground);border-radius:var(--s1);padding:var(--s3) var(--s4);margin:var(--s4) 0 0;list-style:none;font-variant-numeric:tabular-nums}
+.slop .crumb li span{color:var(--muted)}
+.slop .ctas{display:flex;align-items:center;gap:var(--s4);margin-top:var(--s5)}
+.slop .ctas span{font:500 14px/1 var(--body);color:var(--light);cursor:pointer}
+/* hit area: grow each control to at least 44x44 without changing how it looks */
+.slop .ctas span{position:relative}
+.slop .ctas span::after{content:"";position:absolute;left:50%;top:50%;width:max(100%,44px);height:max(100%,44px);transform:translate(-50%,-50%)}
+.slop .ctas span.cta{font-weight:700;color:var(--ground);background:var(--accent);padding:var(--s3) var(--s4);border-radius:var(--s2)}
 </style>
 </head>
 <body>
 <div class="slop" id="cardSlop">
   <div class="box">
